fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "0s"
    val seconds = exposureTimeNs.toDouble() / 1_000_000_000.0
    if (seconds >= 0.5) {
        val rounded = Math.round(seconds * 10.0) / 10.0
        return if (rounded % 1.0 == 0.0) "${rounded.toInt()}s" else "${rounded}s"
    }
    val denominator = Math.round(1.0 / seconds).toInt()
    return "1/${denominator}s"
}

